class Resolver:
    """Common provider resolution vocabulary. Authorization comes from the
    receiving boundary, never from request fields. See RESOLUTION.md for
    selection and refusal semantics."""

    def resolve(self, request: ResolveRequest) -> ResolveResult:
        """Find an authorized ready candidate satisfying an exact acceptable
        contract and all required guarantees. Does not submit work, activate an
        embedded provider, or transfer ownership."""
        raise NotImplementedError


class ResolverClient(Resolver):
    """Calls abstraction.facade/resolver@1 through a transport that exchanges frames."""

    def __init__(self, transport):
        self._transport = transport

    def resolve(self, request: ResolveRequest) -> ResolveResult:
        _service_check("ResolveRequest", request)
        _args = _ResolverResolveArguments()
        _args.request = request
        _arguments = _service_encode(_write_oa_resolver_resolve_arguments, _args, 1)
        _service_decode(_read_oa_resolver_resolve_arguments, _arguments, 1)
        _request = _service_request("abstraction.facade/resolver@1", "Resolve", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.facade/resolver@1", "Resolve")
        _result = _service_decode(_read_oa_resolver_resolve_result, _payload, 1)
        return _result.value


class Caller:
    """The runtime resolver endpoint's echo of its bound caller, for diagnostics
    such as the control panel. Local transport only: a remote service states its
    own authentication and never inherits these proofs."""

    def observe(self) -> CallerObservation:
        """Return what the receiving boundary bound for this connection's caller.
        It is the same Program evidence every runtime-hosted local service
        requires. unavailable means the binding could not be rechecked;
        forbidden is reserved for a boundary policy that withholds the echo;
        invalid for a request this provider cannot interpret. Observe grants,
        checks and changes nothing."""
        raise NotImplementedError


class CallerClient(Caller):
    """Calls abstraction.facade/caller@1 through a transport that exchanges frames."""

    def __init__(self, transport):
        self._transport = transport

    def observe(self) -> CallerObservation:
        _args = _CallerObserveArguments()
        _arguments = _service_encode(_write_oa_caller_observe_arguments, _args, 1)
        _service_decode(_read_oa_caller_observe_arguments, _arguments, 1)
        _request = _service_request("abstraction.facade/caller@1", "Observe", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.facade/caller@1", "Observe")
        _result = _service_decode(_read_oa_caller_observe_result, _payload, 1)
        return _result.value


class Endpoint:
    """The base-protocol description every generated endpoint serves beside its own
    contracts. A registry probes readiness with it over a connection that
    requires the declared program as the server. An endpoint built before this
    service answers unknown_service."""

    def describe(self) -> Description:
        """Describe the services this endpoint hosts and each one's readiness.
        Grants, checks and changes nothing."""
        raise NotImplementedError


